import {request,login,logout,isAdmin,uploadImage} from './backend.js';
const root=document.querySelector('#admin-app');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let properties=[],enquiries=[],settings={},audit=[],activeTab='properties',editing=null,pendingImages=[],dirty=false;
const notice=document.querySelector('#admin-notice');
function say(message,error=false){notice.textContent=message;notice.className=error?'notice error':'notice';notice.hidden=false;}
const option=(value,label,current)=>`<option value="${esc(value)}" ${value===current?'selected':''}>${esc(label)}</option>`;
const field=(name,label,value='',type='text',extra='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
function safeImage(src){try{const u=new URL(src,location.origin);return u.origin===location.origin&&/^\/assets\/property-[1-6]\.jpg$/.test(u.pathname)||u.origin==='https://iylhpckitjozlxgqzflk.supabase.co'&&u.pathname.startsWith('/storage/v1/object/public/property-images/')?u.href:'';}catch{return '';}}
function loginView(){document.querySelector('#admin-shell').hidden=true;root.innerHTML=`<section class="login-card"><img src="/assets/cosmos-mark.svg" width="52" height="52" alt="Cosmos"><p class="eyebrow">COSMOS ADMINISTRATION</p><h1>Welcome back.</h1><p>Sign in to manage your properties and enquiries.</p><form id="login-form">${field('email','Admin email','mngmntstd@gmail.com','email','required autocomplete="username"')}${field('password','Password','','password','required autocomplete="current-password"')}<button class="primary" type="submit">Sign in securely</button><p class="help">First login requires an admin account created in your Cosmos Supabase project. Use your own password; never share it in chat.</p></form><a href="/">← Back to the website</a></section>`;document.querySelector('#login-form').onsubmit=async e=>{e.preventDefault();const b=e.currentTarget.querySelector('button');b.disabled=true;const form=new FormData(e.currentTarget);try{await login(form.get('email').trim(),form.get('password'));e.target.reset();await load();}catch(error){say(error.message,true);b.disabled=false;}};}
async function load(){if(!await isAdmin())return loginView();const results=await Promise.all([request('/rest/v1/properties?select=*&order=sort_order.asc,created_at.desc',{admin:true}),request('/rest/v1/enquiries?select=*&order=created_at.desc&limit=200',{admin:true}),request('/rest/v1/site_settings?select=*&id=eq.1',{admin:true}),request('/rest/v1/audit_log?select=*&order=created_at.desc&limit=20',{admin:true})]);[properties,enquiries]=results;settings=results[2][0];audit=results[3];document.querySelector('#admin-shell').hidden=false;render();}
function render(){root.innerHTML=`<div class="workspace"><header class="workspace-heading"><div><p class="eyebrow">YOUR COSMOS WORKSPACE</p><h1>${{properties:'Property collection',enquiries:'Customer enquiries',settings:'Website settings',activity:'Recent activity'}[activeTab]}</h1></div><a class="secondary" href="/" target="_blank" rel="noopener">View website ↗</a></header><section class="metrics"><div><strong>${properties.filter(p=>p.status==='published').length}</strong><span>Published listings</span></div><div><strong>${properties.filter(p=>p.status==='draft').length}</strong><span>Drafts</span></div><div><strong>${enquiries.filter(e=>e.status==='new').length}</strong><span>New enquiries</span></div><div><strong>${enquiries.length}${enquiries.length===200?'+':''}</strong><span>Recent enquiries</span></div></section><div id="workspace-content"></div></div>`;document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('selected',b.dataset.tab===activeTab));if(activeTab==='properties')propertyList();if(activeTab==='enquiries')enquiryList();if(activeTab==='settings')settingsForm();if(activeTab==='activity')activityList();}
function propertyList(){const host=document.querySelector('#workspace-content');host.innerHTML=`<div class="toolbar"><input id="property-search" type="search" placeholder="Search properties or references" aria-label="Search properties"><button id="add-property" class="primary">+ Add property</button></div><div class="table-scroll"><table><thead><tr><th>Property</th><th>Price (USD)</th><th>Visibility</th><th>Availability</th><th></th></tr></thead><tbody id="property-rows"></tbody></table></div><p class="help">Publish a listing to show it on the website. Archive it to remove it without losing its details.</p>`;function rows(q=''){document.querySelector('#property-rows').innerHTML=properties.filter(p=>(p.name+' '+p.id+' '+p.city).toLowerCase().includes(q.toLowerCase())).map(p=>`<tr><td><strong>${esc(p.name)}</strong><small>${esc(p.id)} · ${esc(p.city)}, ${esc(p.country)}</small></td><td>${Number(p.price).toLocaleString('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0})}${p.kind==='rent'?'/month':''}</td><td><span class="badge ${p.status==='published'?'green':''}">${esc(p.status)}</span></td><td>${esc(p.availability.replace('_',' '))}</td><td><button class="secondary" data-edit="${esc(p.id)}">Edit</button></td></tr>`).join('')||'<tr><td colspan="5">No matching properties.</td></tr>';document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editProperty(properties.find(p=>p.id===b.dataset.edit)));}rows();document.querySelector('#property-search').oninput=e=>rows(e.target.value);document.querySelector('#add-property').onclick=()=>editProperty();}
function editProperty(p){editing=p||null;dirty=false;pendingImages=p?.images?.slice()||[];const value=p||{id:'CS-'+Date.now().toString().slice(-9),slug:'',name:'',city:'',country:'',kind:'sale',type:'house',beds:1,baths:1,area:1,price:0,status:'draft',availability:'available',image:1,sort_order:properties.length,description:'',amenities:[],is_sample:true};const host=document.querySelector('#workspace-content');host.innerHTML=`<div class="editor-heading"><h2>${p?'Edit property':'Add a property'}</h2><button type="button" class="secondary" id="cancel-edit">Back to collection</button></div><form id="property-form" class="panel"><div class="form-grid">${field('name','Property name',value.name,'text','required maxlength="150"')}${field('id','Reference',value.id,'text',`required pattern="[A-Za-z0-9-]{1,40}" ${p?'readonly':''}`)}${field('slug','Page address (slug)',value.slug,'text',`required pattern="[a-z0-9]+(-[a-z0-9]+)*" maxlength="100" ${p?'readonly':''}`)}${field('country','Country',value.country,'text','required maxlength="100"')}${field('city','City',value.city,'text','required maxlength="100"')}<label>Transaction<select name="kind">${['sale','rent'].map(v=>option(v,v,value.kind)).join('')}</select></label><label>Property type<select name="type">${['house','villa','apartment'].map(v=>option(v,v,value.type)).join('')}</select></label>${field('price','Price in USD',value.price,'number','min="0" max="99999999999" step="0.01" required')}${field('beds','Bedrooms',value.beds,'number','min="0" max="100" step="1" required')}${field('baths','Bathrooms',value.baths,'number','min="0" max="100" step="1" required')}${field('area','Area in m²',value.area,'number','min="1" max="9999999" step="0.01" required')}<label>Visibility<select name="status">${['draft','published','archived'].map(v=>option(v,v,value.status)).join('')}</select></label><label>Availability<select name="availability">${['available','under_offer','sold','rented'].map(v=>option(v,v.replace('_',' '),value.availability)).join('')}</select></label>${field('sort_order','Display order (lower is first)',value.sort_order,'number','min="0" step="1" required')}<label>Sample photo fallback<select name="image">${[1,2,3,4,5,6].map(v=>option(v,'Sample image '+v,value.image)).join('')}</select></label></div><label>Description<textarea name="description" rows="5" maxlength="6000">${esc(value.description)}</textarea></label><fieldset><legend>Amenities</legend><div class="checks">${['terrace','pool','garden','parking','workspace'].map(a=>`<label><input type="checkbox" name="amenities" value="${a}" ${value.amenities.includes(a)?'checked':''}>${a}</label>`).join('')}</div></fieldset><label class="check"><input name="is_sample" type="checkbox" ${value.is_sample?'checked':''}>This is an illustrative sample listing</label><section class="image-manager"><h3>Property photos</h3><p class="help">Upload public listing photos only. JPG, PNG or WebP, up to 5 MB each; maximum 12. The first image is the cover.</p><input id="photo-upload" aria-label="Upload property photos" type="file" accept="image/jpeg,image/png,image/webp" multiple><div id="photo-previews" class="photo-previews"></div><p class="help">Removing a photo here removes it from the listing; it remains in Supabase Storage until you delete the file there.</p></section><div class="form-actions"><button class="primary" type="submit">Save property</button>${p?'<button class="danger" id="archive-property" type="button">Archive property</button>':''}<span class="help">Changes take effect on the public website after its next refresh.</span></div></form>`;const form=document.querySelector('#property-form');form.oninput=()=>{dirty=true;};document.querySelector('#cancel-edit').onclick=()=>{if(!dirty||confirm('Discard your unsaved changes?')){dirty=false;propertyList();}};function photos(){document.querySelector('#photo-previews').innerHTML=pendingImages.map((src,i)=>`<figure><img src="${esc(safeImage(src))}" alt="Property photo ${i+1}"><figcaption>${i===0?'Cover':'Photo '+(i+1)} <button type="button" data-cover="${i}" ${i===0?'disabled':''}>Make cover</button><button type="button" data-remove="${i}">Remove</button></figcaption></figure>`).join('');document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{pendingImages.splice(Number(b.dataset.remove),1);dirty=true;photos();});document.querySelectorAll('[data-cover]').forEach(b=>b.onclick=()=>{pendingImages.unshift(pendingImages.splice(Number(b.dataset.cover),1)[0]);dirty=true;photos();});}photos();document.querySelector('#photo-upload').onchange=async e=>{const files=Array.from(e.target.files);if(files.length+pendingImages.length>12){say('Use no more than 12 photos.',true);return;}const save=form.querySelector('[type=submit]');save.disabled=true;e.target.disabled=true;try{for(const f of files){pendingImages.push(await uploadImage(f));dirty=true;photos();}say('Photos uploaded. Save the property to apply them.');}catch(error){say(error.message,true);}finally{save.disabled=false;e.target.disabled=false;e.target.value='';}};form.onsubmit=async e=>{e.preventDefault();const f=new FormData(form);const data=Object.fromEntries(f);for(const n of ['price','beds','baths','area','image','sort_order'])data[n]=Number(f.get(n));data.amenities=f.getAll('amenities');data.is_sample=f.has('is_sample');data.images=pendingImages;data.tag=p?.tag||'';delete data.created_at;const b=form.querySelector('[type=submit]');b.disabled=true;try{await request('/rest/v1/properties'+(p?'?id=eq.'+encodeURIComponent(p.id):''),{method:p?'PATCH':'POST',body:data,admin:true});dirty=false;await load();say('Property saved.');}catch(error){say(error.message,true);b.disabled=false;}};document.querySelector('#archive-property')?.addEventListener('click',async()=>{if(!confirm('Archive this listing? It will disappear from the public website.'))return;try{await request('/rest/v1/properties?id=eq.'+encodeURIComponent(p.id),{method:'PATCH',body:{status:'archived'},admin:true});dirty=false;await load();say('Property archived. You can publish it again later.');}catch(error){say(error.message,true);}});}
function enquiryList(){document.querySelector('#workspace-content').innerHTML=`<div class="toolbar"><p>Latest 200 enquiries. Only approved admins can read these.</p><button class="secondary" id="refresh-enquiries">Refresh</button></div><div class="enquiry-list">${enquiries.map(e=>`<article class="panel"><div class="editor-heading"><div><h2>${esc(e.name)}</h2><a href="mailto:${esc(e.email)}">${esc(e.email)}</a><p class="help">${esc(new Date(e.created_at).toLocaleString())} · ${esc(e.property_id||'General enquiry')}</p></div><span class="badge">${esc(e.status)}</span></div><p class="message">${esc(e.message)}</p><form data-enquiry="${e.id}"><label>Status<select name="status">${['new','in_progress','closed','spam'].map(v=>option(v,v.replace('_',' '),e.status)).join('')}</select></label><label>Internal notes<textarea name="notes" rows="2" maxlength="6000">${esc(e.notes)}</textarea></label><button class="secondary" type="submit">Save enquiry</button></form></article>`).join('')||'<div class="panel"><h2>No enquiries yet.</h2><p>Website form submissions will appear here. WhatsApp messages and direct emails remain in their respective apps.</p></div>'}</div>`;document.querySelector('#refresh-enquiries').onclick=()=>load().catch(e=>say(e.message,true));document.querySelectorAll('[data-enquiry]').forEach(form=>form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('button');button.disabled=true;try{await request('/rest/v1/enquiries?id=eq.'+form.dataset.enquiry,{method:'PATCH',body:Object.fromEntries(new FormData(form)),admin:true});await load();say('Enquiry updated.');}catch(error){say(error.message,true);button.disabled=false;}});}
function settingsForm(){document.querySelector('#workspace-content').innerHTML=`<form id="settings-form" class="panel settings-form"><h2>Contact details & colours</h2><p>These settings apply across the public website.</p>${field('contact_email','Public contact email',settings.contact_email,'email','required')}${field('whatsapp_number','WhatsApp number (country code, digits only)',settings.whatsapp_number,'text','required pattern="[1-9][0-9]{7,14}"')}${field('primary_color','Primary colour',settings.primary_color,'color','required')}${field('accent_color','Accent colour',settings.accent_color,'color','required')}<button type="submit" class="primary">Save website settings</button><p class="help">Your admin sign-in address is separate from the public contact email. Changing contact details does not change who can log in.</p></form>`;document.querySelector('#settings-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{await request('/rest/v1/site_settings?id=eq.1',{method:'PATCH',body:Object.fromEntries(new FormData(e.target)),admin:true});await load();say('Website settings updated. Refresh the public website to see them.');}catch(error){say(error.message,true);b.disabled=false;}};}
function activityList(){document.querySelector('#workspace-content').innerHTML=`<div class="panel"><h2>Latest 20 changes</h2><ul class="activity">${audit.map(a=>`<li><strong>${esc(a.action.toLowerCase())} · ${esc(a.entity)}</strong><span>${esc(a.record_id)} · ${esc(new Date(a.created_at).toLocaleString())}</span></li>`).join('')||'<li>No changes yet.</li>'}</ul></div>`;}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{if(dirty&&!confirm('Discard unsaved property changes?'))return;dirty=false;activeTab=b.dataset.tab;render();});document.querySelector('#sign-out').onclick=async()=>{if(dirty&&!confirm('Discard changes and sign out?'))return;dirty=false;await logout();notice.hidden=true;loginView();};window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
load().catch(error=>{say(error.message,true);loginView();});
